import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"岛屿任务、生成器与资源额度","description":"了解科技空岛的任务奖励、漂流鱼竿成长，以及矿物生成器和全岛共享额度的关系。","frontmatter":{"title":"岛屿任务、生成器与资源额度","description":"了解科技空岛的任务奖励、漂流鱼竿成长，以及矿物生成器和全岛共享额度的关系。"},"headers":[],"relativePath":"skyblock/resources.md","filePath":"skyblock/resources.md"}`),a={name:`skyblock/resources.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="岛屿成长-任务、生成器与资源额度" tabindex="-1">岛屿成长：任务、生成器与资源额度 <a class="header-anchor" href="#岛屿成长-任务、生成器与资源额度" aria-label="Permalink to “岛屿成长：任务、生成器与资源额度”">​</a></h1><p>空岛的材料来源需要一点规划。任务帮你找到阶段目标，生成器提供矿物来源，共享额度则决定资源生产的恢复节奏。</p><h2 id="missions" tabindex="-1">先看任务，再决定今天做什么 <a class="header-anchor" href="#missions" aria-label="Permalink to “先看任务，再决定今天做什么”">​</a></h2><p>在 <code>/is panel</code> 中选择任务，或直接打开：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is missions</span></span></code></pre></div><p>任务包含矿工、猎杀者、农夫、渔夫和探险家等方向。打开具体任务，确认目标、统计条件和奖励，再安排采集或建设。</p><p>奖励可以包含游戏内货币、物资，以及与生成器升级或鱼竿芯片有关的内容，具体以当前菜单为准。机器自动生产的材料是否计入某项任务，取决于其统计条件，不能一概而论。</p><h2 id="rods" tabindex="-1">鱼竿如何成长 <a class="header-anchor" href="#rods" aria-label="Permalink to “鱼竿如何成长”">​</a></h2><p>漂流鱼竿的升阶路线会用到<strong>对应升级芯片、前一级鱼竿与指定材料</strong>。拿到芯片后先查看当前升级说明，不要把普通物品当作芯片替代。</p><ul><li>初始鱼竿的正常发放方式尚待确认。</li><li>第六级星海竿已有奖池配置，完整获取／升阶流程仍待确认。</li><li>升级后奖池会改变，<strong>不自动保留低等级的全部掉落</strong>。有特定材料需求时，先查 <a href="./fishing-rewards.html">完整奖池</a>。</li></ul><p>本站暂不列未经玩家完整验证的升阶材料表，避免照表投入材料后发现与当前服内要求不同。</p><h2 id="矿物生成器不是一成不变的" tabindex="-1">矿物生成器不是一成不变的 <a class="header-anchor" href="#矿物生成器不是一成不变的" aria-label="Permalink to “矿物生成器不是一成不变的”">​</a></h2><p>通过岛屿面板查看升级，或输入：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is upgrade</span></span></code></pre></div><p>生成器可以逐步升级，产出方向从基础矿物扩展到科技工业需要的原料。铁、铜、红石，以及锇、锡、铅、锌等材料，可以逐渐纳入岛屿的生产规划；实际可产资源取决于当前生成器等级。</p><p>等级决定可抽取的资源范围，实际产出还会受到共享额度的影响。精确矿表、升级条件和费用请以当前服内界面为准。</p><h2 id="quota" tabindex="-1">全岛共享的矿物生成额度 <a class="header-anchor" href="#quota" aria-label="Permalink to “全岛共享的矿物生成额度”">​</a></h2><p>这里的额度限制的是<strong>新生成的矿物方块</strong>，不是背包、仓库里已经拥有的材料。</p><table tabindex="0"><thead><tr><th>想知道的事</th><th>规则说明</th></tr></thead><tbody><tr><td>谁共用额度？</td><td>同一座岛的成员共用一组额度，按整岛计算，并非每人一份；跨维度也共享。</td></tr><tr><td>用完就没有了吗？</td><td>额度有容量上限，并按时间恢复。容量与恢复速度是两件事。</td></tr><tr><td>普通矿与深层矿分开算吗？</td><td>同组的普通矿和深层矿共用额度。</td></tr><tr><td>某组额度不足会怎样？</td><td>当前配置会用普通石头替代该次矿物生成。</td></tr><tr><td>多建几套生成器能绕过吗？</td><td>设备数量不会增加整岛共享的额度池。</td></tr><tr><td>所有模组机器都受这个规则约束吗？</td><td>不能这样推断；这里说明的是已接入的矿物生成机制，不是所有模组产出的统一上限。</td></tr></tbody></table><p>在需要查询的位置输入：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/bq status</span></span></code></pre></div><p>先核对当前位置所属范围的额度，再安排生产。多人同岛时，也记得与其他成员商量用料，避免几条产线同时等待同一种矿物。</p><div class="tip custom-block"><p class="custom-block-title">把原料用得更合适</p><p>暂时缺矿时，可以先处理库存、补齐仓储或调整加工链。把每份材料用在需要的地方，也是科技空岛的一部分。</p></div><p>继续查阅：<a href="./fishing-rewards.html">漂流钓鱼奖池</a> · <a href="./commands.html">常用命令</a> · <a href="./getting-started.html">返回新手入门</a></p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};